#!/usr/bin/env bash
# Compile the host's colour conversion (crates/capture/src/d3d11_convert.hlsl)
# and write its bytecode as Rust constants beside it.
#
# Run by hand on Windows, never from a build script: the bytecode is committed
# so that no build machine needs the shader compiler, and nothing compiles a
# shader at run time. Run from a shell that sees the SDK's `fxc` (a Visual
# Studio x64 developer environment does):
#
#   scripts/gen-d3d11-convert.sh
#
# The compiler's banner is written into the generated file's first lines, so a
# regeneration with another one shows in the diff.

set -euo pipefail

# Git Bash rewrites arguments that look like paths, and the compiler's options
# begin with "/"; every path handed to a native program is converted by hand.
export MSYS2_ARG_CONV_EXCL='*'
py=""
for candidate in python3 python; do
    if "$candidate" -c '' 2>/dev/null; then py="$candidate"; break; fi
done
[ -n "$py" ] || { echo "no python" >&2; exit 1; }

root="$(cd "$(dirname "$0")/.." && pwd)"
src="$root/crates/capture/src/d3d11_convert.hlsl"
out="$root/crates/capture/src/d3d11_convert.rs"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

# The whole help is read, so the compiler never writes into a closed pipe.
banner="$( (fxc /? 2>&1 || true) | sed -n 1p | tr -d '\r')"
echo "compiling the conversion with: $banner"
variants=(NV12 P010 AYUV Y410)
# One compiler run: a target, an entry point, a layout and the file it writes.
compile() {
    fxc /nologo /T "$1" /E "$2" /O3 /WX /Qstrip_debug /Qstrip_reflect /Qstrip_priv \
        /D "$3=1" /Fo "$(cygpath -w "$work/$4.cso")" "$(cygpath -w "$src")" >/dev/null
}
for v in "${variants[@]}"; do
    # The compute pass, and the draw's pixel shaders: a plane each of the
    # two-plane layouts, the one word of the packed ones.
    compile cs_5_0 main "$v" "$v"
    case "$v" in
        NV12 | P010)
            compile ps_5_0 luma "$v" "${v}_LUMA"
            compile ps_5_0 chroma "$v" "${v}_CHROMA"
            ;;
        *) compile ps_5_0 pixel "$v" "${v}_PIXEL" ;;
    esac
done
# The draw's vertex shader, which no layout changes.
compile vs_5_0 vertex NV12 VERTEX

# The interpreter may be a native one, which reads native paths only.
"$py" - "$(cygpath -w "$work")" "$(cygpath -w "$out")" "$banner" "${variants[@]}" <<'PY'
import sys

work, dst, banner, variants = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4:]
names = {
    "NV12": "the two-plane layout at eight bits",
    "P010": "the two-plane layout at ten bits in sixteen",
    "AYUV": "the packed full-chroma layout at eight bits",
    "Y410": "the packed full-chroma layout at ten bits",
}
entries = []
for v in variants:
    entries.append((v, "The conversion into %s." % names[v]))
    if v in ("NV12", "P010"):
        entries.append((v + "_LUMA", "The draw of the luma plane of %s." % names[v]))
        entries.append((v + "_CHROMA", "The draw of the chroma plane of %s." % names[v]))
    else:
        entries.append((v + "_PIXEL", "The draw of %s." % names[v]))
entries.append(("VERTEX", "The vertex shader every draw shares."))
lines = [
    "// Generated by scripts/gen-d3d11-convert.sh from d3d11_convert.hlsl. Do not edit.",
    "// %s." % banner,
    "",
]
for name, doc in entries:
    code = open("%s/%s.cso" % (work, name), "rb").read()
    lines.append("/// %s" % doc)
    lines.append("pub(super) const %s: &[u8] = &[" % name)
    for i in range(0, len(code), 16):
        lines.append("    " + " ".join("0x%02x," % b for b in code[i:i + 16]))
    lines.append("];")
    lines.append("")
open(dst, "w", encoding="ascii", newline="\n").write("\n".join(lines))
print("  %d shaders" % len(entries))
PY

rustfmt --edition 2024 "$(cygpath -w "$out")"
